private bool UpdateLockToDateForSelected()
{
    string strEmployeeIDList = gvData.GetIDListSelected("IsSelected", "EmployeeID");
    if (strEmployeeIDList == "")
    {
        MessageManager.Warning("Bạn phải tick chọn nhân viên cần cập nhật ngày khóa!");
        return false;
    }

    if (dtmLockToDate.EditValueDate == null)
    {
        MessageManager.Warning("Vui lòng nhập ngày khóa sửa!");
        dtmLockToDate.Focus();
        return false;
    }

    if (MessageManager.Confirm("Cập nhật ngày khóa sửa cho các nhân viên đã chọn?") != DialogResult.Yes)
        return false;

    HRS_Employee objEmployee = new HRS_Employee();
    if (!objEmployee.UpdateLockToDate(strEmployeeIDList, dtmLockToDate.EditValueDate, UserSession.Username))
    {
        if (objEmployee.ErrorException != null)
            ErrorManager.Error("Cập nhật ngày khóa sửa thất bại!\r\n" + objEmployee.ErrorException.Message);
        else
            MessageManager.Error("Cập nhật ngày khóa sửa thất bại!");
        return false;
    }

    DateTime dtmLock = dtmLockToDate.EditValueDate.Value;
    for (int i = 0; i < dtbData.Rows.Count; i++)
    {
        DataRow drw = dtbData.Rows[i];
        if (Convert.ToBoolean(drw["IsSelected"]))
        {
            drw[HRS_Employee.C_LockToDate] = dtmLock;
        }
    }

    string strActionLog = String.Format("Ngày khóa sửa: {0:dd/MM/yyyy}\r\nDanh sách mã NV (EmployeeID): {1}", dtmLock, strEmployeeIDList);
    new SystemObject.SYS_ActionLog().WriteActionLog("Cập nhật ngày khóa sửa nhân viên", strActionLog, SystemObject.ActionLogType.EDIT, 2, UserSession.Username);

    MessageManager.Info("Đã cập nhật ngày khóa sửa thành công!");
    return true;
}

